package com.boss.workforce.controller; import com.boss.common.security.TenantContext; import com.boss.workforce.domain.*; import com.boss.workforce.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/workforce") public class WorkforceController {private final AttritionEventRepository a; public WorkforceController(AttritionEventRepository a){this.a=a;} @GetMapping("/attrition") public List<AttritionEvent> attrition(){return a.findByTenantId(TenantContext.requireTenantId());} @PostMapping("/attrition") public AttritionEvent addAttrition(@RequestBody AttritionEvent x){x.setTenantId(TenantContext.requireTenantId());return a.save(x);} @GetMapping("/summary") public Map<String,Object> summary(){var t=TenantContext.requireTenantId();var events=a.findByTenantId(t);return Map.of("attritionEvents",events.size());}}
